export const meta = {
  name: 'maestro-full-review',
  description: 'Full review of the Maestro repository — correctness, consistency, quick-win improvements, and skill ideas',
  phases: [
    { title: 'Read', detail: 'Load all files into reviewer context' },
    { title: 'Review', detail: 'Parallel deep review across dimensions' },
    { title: 'Synthesise', detail: 'Compile findings and skill ideas' },
  ],
}

const ROOT = '/Users/gaelrobin/Desktop/Work/maestro'

// ─── Phase 1: read every file ───────────────────────────────────────────────
phase('Read')

const FILES = [
  // agents
  'agents/backend-agent.md',
  'agents/challenger.md',
  'agents/changelog-agent.md',
  'agents/e2e-qa-tester.md',
  'agents/frontend-agent.md',
  'agents/grooming-agent.md',
  'agents/lead-reviewer.md',
  'agents/pr-agent.md',
  'agents/qa-engineer.md',
  'agents/release-agent.md',
  'agents/test-writer.md',
  'agents/ticket-writer.md',
  // commands
  'commands/docs.md',
  'commands/dod.md',
  'commands/e2e.md',
  'commands/issue-workflow.md',
  'commands/knowledge-graph.md',
  'commands/onboard-project.md',
  'commands/orchestrator.md',
  'commands/po-changelog.md',
  'commands/pr.md',
  'commands/sprint-planner.md',
  'commands/test.md',
  'commands/wordpress-compliance.md',
  // supporting
  'commands/orchestrator/html-log-format.md',
  'commands/issue-workflow/refs/pr-template.md',
  'commands/issue-workflow/scripts/init-pr-draft.sh',
  'commands/issue-workflow/scripts/issue-sync.sh',
  'commands/issue-workflow/scripts/make-issue-branch.sh',
  'commands/issue-workflow/scripts/slack-notify.js',
  // bin
  'bin/dev-up.sh',
  'bin/dev-down.sh',
  'bin/build-knowledge-graph.js',
  // template & docs
  '.template/maestro.json',
  'AGENTS.md',
  'README.md',
  'WHY_MAESTRO.md',
  // specs
  'specs/phpcs/escaped-output.md',
  'specs/phpcs/nonce-verification-recommended.md',
  'specs/phpcs/validated-sanitized-input.md',
]

const contents = await parallel(FILES.map(f => () =>
  agent(`Read the file at ${ROOT}/${f} and return its full content verbatim as a JSON object: { "path": "${f}", "content": "<full content>" }. Do not summarise — return the raw text.`, {
    label: `read:${f.split('/').pop()}`,
    phase: 'Read',
    schema: {
      type: 'object',
      properties: {
        path: { type: 'string' },
        content: { type: 'string' },
      },
      required: ['path', 'content'],
    },
  })
))

const corpus = contents.filter(Boolean).map(f => `=== ${f.path} ===\n${f.content}`).join('\n\n')

// ─── Phase 2: parallel review across 5 dimensions ───────────────────────────
phase('Review')

const REVIEW_SCHEMA = {
  type: 'object',
  properties: {
    dimension: { type: 'string' },
    findings: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          file: { type: 'string' },
          severity: { type: 'string', enum: ['fix', 'improvement', 'nitpick'] },
          title: { type: 'string' },
          detail: { type: 'string' },
          suggestion: { type: 'string' },
        },
        required: ['file', 'severity', 'title', 'detail', 'suggestion'],
      },
    },
  },
  required: ['dimension', 'findings'],
}

const SKILL_SCHEMA = {
  type: 'object',
  properties: {
    ideas: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          name: { type: 'string' },
          trigger: { type: 'string' },
          value: { type: 'string' },
          effort: { type: 'string', enum: ['low', 'medium', 'high'] },
          priority: { type: 'string', enum: ['must-have', 'nice-to-have', 'future'] },
        },
        required: ['name', 'trigger', 'value', 'effort', 'priority'],
      },
    },
  },
  required: ['ideas'],
}

const [crossRefs, cliCorrectness, agentQuality, templateQuality, skillIdeas] = await parallel([

  // 1. Cross-reference consistency
  () => agent(`You are a consistency auditor. Here is the complete Maestro repository content:\n\n${corpus}\n\nCheck for broken or inconsistent cross-references:\n- Commands that spawn agents by name — does the agent file exist with that name?\n- Agents that reference skills or config keys (e.g. maestro.json fields like ai.slug, ai.temp_root, ai.repo) — are those fields present in the template?\n- Scripts referenced in commands (e.g. bash path/to/script.sh) — do those files exist in the repo?\n- Commands that reference other commands by slash-name — are those names correct?\n- maestro.json template fields referenced in agents/commands — are they consistent?\n\nReturn all findings. Be specific: quote the exact broken reference and where it appears.`, {
    label: 'review:cross-references',
    phase: 'Review',
    schema: REVIEW_SCHEMA,
  }),

  // 2. Shell script / JS correctness
  () => agent(`You are a shell script and JavaScript code reviewer. Here is the complete Maestro repository content:\n\n${corpus}\n\nFocus ONLY on these files: bin/dev-up.sh, bin/dev-down.sh, bin/build-knowledge-graph.js, commands/issue-workflow/scripts/init-pr-draft.sh, commands/issue-workflow/scripts/issue-sync.sh, commands/issue-workflow/scripts/make-issue-branch.sh, commands/issue-workflow/scripts/slack-notify.js\n\nReview for:\n- Correctness bugs (wrong flags, missing error handling, broken pipe, unquoted variables)\n- Idempotency issues (scripts claim to be idempotent — are they?)\n- Hardcoded values that should be config-driven\n- Missing shebang, set -euo pipefail, or other safety boilerplate\n- Node.js script quality: error handling, missing edge cases\n- Anything that would silently fail\n\nReturn all findings with exact line-level detail.`, {
    label: 'review:scripts',
    phase: 'Review',
    schema: REVIEW_SCHEMA,
  }),

  // 3. Agent instruction quality
  () => agent(`You are an expert AI agent prompt engineer. Here is the complete Maestro repository content:\n\n${corpus}\n\nReview all files under agents/ for instruction quality:\n- Are the instructions clear and unambiguous for an LLM to follow?\n- Are there steps that are vague ("do X appropriately") without concrete criteria?\n- Are there missing edge cases (e.g. what if a file doesn't exist? what if a GitHub API call fails?)\n- Are quality guardrails present and specific?\n- Are there contradictions between steps?\n- Do agents correctly read maestro.json before acting (as required)?\n- Are there any steps that overlap with another agent's responsibility in a confusing way?\n- Tone: are instructions imperative and precise, or wishy-washy?\n\nReturn actionable findings only — not generic praise.`, {
    label: 'review:agent-quality',
    phase: 'Review',
    schema: REVIEW_SCHEMA,
  }),

  // 4. Template and docs quality
  () => agent(`You are a developer experience reviewer. Here is the complete Maestro repository content:\n\n${corpus}\n\nReview: .template/maestro.json, AGENTS.md, README.md, WHY_MAESTRO.md, commands/onboard-project.md\n\n- Does the maestro.json template cover all fields referenced by agents and commands? Are any fields missing from the template that agents expect?\n- Is AGENTS.md a useful coordination document or is it stale/incomplete?\n- Does README.md accurately describe the current state of the project (commands, agents, structure)?\n- Does onboard-project.md reference the correct step numbers now that Step 8 was added?\n- Are there fields in maestro.json with null defaults that should have better placeholder values or notes?\n- Are the _note fields in maestro.json clear and helpful?\n\nReturn actionable findings only.`, {
    label: 'review:docs-template',
    phase: 'Review',
    schema: REVIEW_SCHEMA,
  }),

  // 5. Skill gap analysis
  () => agent(`You are a product strategist for a WordPress plugin AI delivery pipeline. Here is the complete Maestro repository content:\n\n${corpus}\n\nMaestro is used by wp-media (makers of WP Rocket, BackWPup, Imagify) as an AI-powered delivery pipeline. It has agents and skills for: issue grooming, implementation (backend/frontend), PR creation, QA, changelog generation, sprint planning, onboarding new projects, and more.\n\nAnalyse the gap between what exists and what a high-performing plugin team would benefit from. Think about the full software delivery lifecycle: planning → grooming → implementation → review → QA → release → monitoring → support.\n\nSuggest new skills/commands that would provide real, concrete value. For each idea:\n- name: short slug (e.g. "hotfix", "retrospective", "dependency-audit")\n- trigger: when would a dev naturally reach for this? (concrete scenario)\n- value: what pain does it solve or what time does it save?\n- effort: low/medium/high to build\n- priority: must-have / nice-to-have / future\n\nBe specific and practical. Avoid generic ideas. Think about what wp-media specifically needs based on the codebase clues (WordPress plugin, free/pro split, changelog workflow, license keys, cloud storage, E2E tests, etc.).`, {
    label: 'review:skill-ideas',
    phase: 'Review',
    schema: SKILL_SCHEMA,
  }),
])

// ─── Phase 3: synthesise ─────────────────────────────────────────────────────
phase('Synthesise')

const allFindings = [crossRefs, cliCorrectness, agentQuality, templateQuality]
  .filter(Boolean)
  .flatMap(r => r.findings || [])

const synthesis = await agent(
  `You are the lead engineer synthesising a code review of the Maestro AI pipeline repository.

Here are all findings from four review dimensions:

${JSON.stringify(allFindings, null, 2)}

And here are skill gap ideas:

${JSON.stringify(skillIdeas?.ideas || [], null, 2)}

Produce a clean, structured report:

## Quick fixes (severity: fix)
List each fix with: file, what's wrong, exact change needed.

## Improvements (severity: improvement)
List each improvement with: file, what to improve, why it matters.

## Nitpicks (severity: nitpick)
Brief bullet list only — file + one line each.

## Skill ideas
Group by priority (must-have / nice-to-have / future). For each: name, trigger scenario, value, effort.

Be direct and actionable. No filler. If a finding is duplicated across dimensions, merge it.`,
  { label: 'synthesise', phase: 'Synthesise' }
)

return { synthesis, totalFindings: allFindings.length, skillIdeasCount: skillIdeas?.ideas?.length || 0 }

